function sweepContact(ball, brick, px, py) {
  const r = ball.r;
  const x1 = brick.x - r, x2 = brick.x + brick.w + r;
  const y1 = brick.y - r, y2 = brick.y + brick.h + r;
  const dx = ball.x - px;
