  let tMinY = -Infinity, tMaxY = Infinity;
  if (dx !== 0) {
    const a = (x1 - px) / dx;
    const b = (x2 - px) / dx;
    tMinX = Math.min(a, b);
    tMaxX = Math.max(a, b);
  } else if (!(px > x1 && px < x2)) {
    return null; // parallel to x, never enters the box
  }
  if (dy !== 0) {
    const a = (y1 - py) / dy;
    const b = (y2 - py) / dy;
    tMinY = Math.min(a, b);
    tMaxY = Math.max(a, b);
  } else if (!(py > y1 && py < y2)) {
    return null;
  }

  const tIn = Math.max(tMinX, tMinY);
  const tOut = Math.min(tMaxX, tMaxY);
  if (tIn > tOut || tIn <= 0 || tIn > 1) return null;

  let face;
  if (Math.abs(tMinX - tMinY) < EPS) face = 'corner';
  else if (tMinX > tMinY) face = dx > 0 ? 'left' : 'right';
  else face = dy > 0 ? 'top' : 'bottom';

  return {
    brick,
    t: tIn,
    face,
    x: px + dx * tIn,
    y: py + dy * tIn,
  };
}
