// --- Brick collision resolution (issue #1) --------------------------------

// The ball is a circle and a brick an AABB. Inflating the brick by the ball
// radius turns the test "does the circle overlap the rectangle?" into the
// point test "is the centre inside the inflated box?" — used below for both
// the overlap and the sweep. Every contact is resolved exactly once:
//
//  - per face: the axis with the SMALLER penetration is the face that was
//    hit — flip that component, leave the other untouched;
//  - corner: equal penetrations on both axes mean a diagonal hit — flip both;
//  - push out: the ball is repositioned outside the brick, or it still
//    overlaps on the next frame and re-flips forever (sticky bounce);
//  - neighbours: the 8 px grid gap is narrower than the 14 px ball, so a seam
//    overlaps two bricks in the same pass. Contacts are resolved one at a
//    time and each resolution pushes the ball out first, so the bounce only
//    ever applies once (`vy = -vy` twice would cancel and let the ball
//    through);
//  - tunnelling: detection is discrete, so at level 6 a stuttered 50 ms frame
//    (35.5 px) can jump the ball over a brick (34 px to cross). The sweep
//    between the previous position (saved by step() as px/py) and the current
//    one catches the crossing and bounces the ball at the entry point.
const EPS = 1e-9;

// Returns the earliest contact of the ball with any live brick, or null.
// `px/py` is where the ball was before the current step (for the sweep).
function earliestContact(ball, bricks, px, py) {
  let best = null;
  for (const brick of bricks) {
    if (!brick.alive) continue;
    const contact = brickContact(ball, brick, px, py);
    if (contact && (!best || contact.t < best.t)) best = contact;
  }
  return best;
}

// Contact of the ball with one brick: overlap first (t = 0), then sweep.
function brickContact(ball, brick, px, py) {
  const overlap = overlapContact(ball, brick);
  if (overlap) return overlap;
  return sweepContact(ball, brick, px, py);
}

// Overlap at the current position. Returns {brick, t: 0, face, x, y} where
// x/y is the push-out position.
function overlapContact(ball, brick) {
  const r = ball.r;
  const x1 = brick.x - r;
  const x2 = brick.x + brick.w + r;
  const y1 = brick.y - r;
  const y2 = brick.y + brick.h + r;
  if (!(ball.x > x1 && ball.x < x2 && ball.y > y1 && ball.y < y2)) return null;

  const pens = [
    { face: 'left', d: ball.x - x1, x: x1, y: ball.y },
    { face: 'right', d: x2 - ball.x, x: x2, y: ball.y },
    { face: 'top', d: ball.y - y1, x: ball.x, y: y1 },
    { face: 'bottom', d: y2 - ball.y, x: ball.x, y: y2 },
  ];
  pens.sort((a, b) => a.d - b.d);

  if (Math.abs(pens[0].d - pens[1].d) < EPS) {
    // Corner: the two smallest penetrations are adjacent faces.
    const horizontal = pens[0].face === 'left' || pens[0].face === 'right' ? pens[0] : pens[1];
    const vertical = pens[0].face === 'top' || pens[0].face === 'bottom' ? pens[0] : pens[1];
    return { brick, t: 0, face: 'corner', x: horizontal.x, y: vertical.y };
  }
  return { brick, t: 0, face: pens[0].face, x: pens[0].x, y: pens[0].y };
}

// Sweep between the previous position (px/py) and the current one. Returns
// the first entry into the inflated box, or null.
function sweepContact(ball, brick, px, py) {
  const r = ball.r;
  const x1 = brick.x - r;
  const x2 = brick.x + brick.w + r;
  const y1 = brick.y - r;
  const y2 = brick.y + brick.h + r;
  const dx = ball.x - px;
  const dy = ball.y - py;
  if (dx === 0 && dy === 0) return null;

  let tMinX = -Infinity;
  let tMaxX = Infinity;
  let tMinY = -Infinity;
  let tMaxY = Infinity;
  if (dx !== 0) {
    const a = (x1 - px) / dx;
    const b = (x2 - px) / dx;
    tMinX = Math.min(a, b);
    tMaxX = Math.max(a, b);
  } else if (!(px > x1 && px < x2)) {
    return null; // path parallel to x, never reaches the box
  }
  if (dy !== 0) {
    const a = (y1 - py) / dy;
    const b = (y2 - py) / dy;
    tMinY = Math.min(a, b);
    tMaxY = Math.max(a, b);
  } else if (!(py > y1 && py < y2)) {
    return null;
  }

  const tIn = Math.max(tMinX, tMinY);
  const tOut = Math.min(tMaxX, tMaxY);
  if (tIn > tOut || tIn <= 0 || tIn > 1) return null;

  let face;
  if (Math.abs(tMinX - tMinY) < EPS) {
    face = 'corner';
  } else if (tMinX > tMinY) {
    face = dx > 0 ? 'left' : 'right';
  } else {
    face = dy > 0 ? 'top' : 'bottom';
  }

  return {
    brick,
    t: tIn,
    face,
    x: px + dx * tIn,
    y: py + dy * tIn,
  };
}

// Applies one contact: destroys the brick, scores it, pushes the ball out and
// reflects the velocity on the hit face (the other component is untouched).
function applyContact(state, contact) {
  const { ball } = state;
  const brick = contact.brick;
  brick.alive = false;
  state.combo += 1;
  state.score += scoreForBrick(brick, state.combo);

  ball.x = contact.x;
  ball.y = contact.y;

  if (contact.face === 'corner') {
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
  } else if (contact.face === 'left') {
    ball.vx = -Math.abs(ball.vx);
  } else if (contact.face === 'right') {
    ball.vx = Math.abs(ball.vx);
  } else if (contact.face === 'top') {
    ball.vy = -Math.abs(ball.vy);
  } else {
    ball.vy = Math.abs(ball.vy);
  }
}

// Resolves every contact of the ball with the bricks for the current frame.
// Contacts are handled one at a time, earliest first; after each resolution
// the ball has been pushed out, so a seam overlapping two bricks only bounces
// once. The remaining motion of the step is discarded (classic arcade
// behaviour): what matters is that the ball ends the frame outside every
// brick, heading away from the face it just hit.
function resolveBricks(state) {
  const { ball, bricks } = state;
  let px = ball.px ?? ball.x;
  let py = ball.py ?? ball.y;

  let guard = 0;
  while (guard++ < bricks.length + 1) {
    const contact = earliestContact(ball, bricks, px, py);
    if (!contact) break;
    applyContact(state, contact);
    // The sweep was for this step's motion only; from here on the ball
    // stands still, so only the overlap test applies.
    px = ball.x;
    py = ball.y;
  }
}
